        "question": "Bir sıvının akmaya karşı gösterdiği dirence **viskozite** denir. Viskozitesi büyük olan sıvıların akıcılığı düşüktür (yavaş akarlar).\nBuna göre aşağıdaki sıvı çiftlerinden hangisinde birinci sıvının viskozitesi ikinciden **daha büyüktür**?\n*(Bütün sıvıların aynı oda sıcaklığında olduğu varsayılacaktır).*",
