        "question": "İdeal gazların davranışlarını açıklamak için bilim insanları (Boyle, Charles, Gay-Lussac, Avogadro) bazı yasalar geliştirmiştir.\nAşağıda verilen, gazın sahip olduğu iki değişken arasındaki orantı eşleştirmelerinden hangisi **doğrudur**?",
