        "question": "Bir deney tüpünün (cam borunun) sol ucundan X gazı, sağ ucundan Y gazı aynı anda ve aynı sıcaklıkta gönderiliyor.\nGazlar, cam borunun tam ortasında değil de **sol uca daha yakın** bir noktada ilk kez karşılaşıp reaksiyona giriyorlar.\nBu deneye göre;\nI. Y gazı, X gazına göre boru içinde daha hızlı ilerlemiştir.\nII. X molekülünün mol kütlesi (ağırlığı), Y molekülünün mol kütlesinden daha büyüktür (X daha ağırdır).\nIII. X gazının ortalama kinetik enerjisi, Y gazının ortalama kinetik enerjisinden daha düşüktür.\nyargılarından hangilerine **kesinlikle** ulaşılır?",
