        "solution": "İkisi de 16'şar gram olsun.\n$CH_4$ ($16 \\ g/mol$): $16/16 = 1 \\ mol$.\n$H_2$ ($2 \\ g/mol$): $16/2 = 8 \\ mol$.\nA) $H_2$'nin molü (8) , $CH_4$'ün molünden (1) tam 8 kat fazladır. (Doğru).\nB) $H_2$'nin molü çok olduğu için kabın duvarlarına daha çok çarpar (Kısmi basıncı 8 kat daha büyüktür). (Doğru).\nC) Aynı kaptalar, sıcaklıkları aynı, ortalama kinetik enerjileri eşittir. (Doğru).\nD) Hız kökle ters orantılıydı. $\\sqrt{16/2} = \\sqrt{8} = 2\\sqrt{2}$. $H_2$ daha hızlıdır. (Doğru).\nE) \"Gazlar kabı yarı yarıya paylaşır\" İFADESİ KESİNLİKLE YANLIŞTIR. Kapalı bir kapta bulunan her gaz, KABIN TAMAMINI Hacim olarak kabul eder. Yani $H_2$'nin hacmi = $V$, $CH_4$'ün hacmi = $V$'dir. Yarı yarıya paylaşmak sıvı ve katılara aittir. (E yanlış)."
