        "question": "Maddenin farklı hâllerinde bulunan;\n- $X$: Yalnız titreşim hareketi yapan, belirli bir şekli ve hacmi olan, sıkıştırılamayan bir maddedir.\n- $Y$: Titreşim, dönme ve öteleme hareketi yapabilen, tanecikleri arası boşluğu $X$'ten çok fazla olan, sıkıştırılabilen ve akışkan olan bir maddedir.\n- $Z$: Isıtılıp enerjisi çok yükseltilmiş, serbest elektronlar ve iyonlardan oluşan elektriği çok iyi ileten bir akışkandır.\nYukarıdaki bilgilere göre $X, Y$ ve $Z$'nin madde hâlleri aşağıdakilerden hangisinde doğru verilmiştir?",
