        "question": "Kapalı ve ısıtılmış bir ortamda saf bir sıvının denge buhar basıncı, sıvının aynı sıcaklıktaki kaynama anına oranla çok daha düşüktür. \nBuna göre bir sıvının kaynama noktası ile buhar basıncı ilişkisini açıklayan en doğru ifade aşağıdakilerden hangisidir?",
