        "correctAnswer": "B",
        "difficulty": "medium",
        "solution": "Hacim Sabit ($V$).\nBaşlangıç: $4 \\ g$ $He$ (Mol = $4/4 = 1 \\ mol$). Basınç = $1 \\ atm$.\nÖzkütle = $4 / V$.\nSonra kaba $16 \\ g$ $CH_4$ ekleniyor. $CH_4$ mol = $16 / 16 = 1 \\ mol$.\nKütle durumu: İçeride $4 \\ g$ vardı, $16 \\ g$ daha geldi. Toplam kütle $4+16 = 20 \\ g$ oldu. Kütle $4$'ten $20$'ye çıktı (5 KATINA ÇIKTI). Hacim sabit olduğuna göre Özkütle ($d$) 5 KATINA ÇIKAR.\nMol (Basınç) durumu: İçeride $1 \\ mol$ gaz vardı ($1 \\ atm$ yapıyordu), $1 \\ mol$ daha gaz geldi. Toplam $2 \\ mol$ gaz oldu. Mol sayısı $1$'den $2$'ye (2 KATINA) çıktığı için Basınç da 2 KATINA ÇIKAR (Son basınç $2 \\ atm$ olur).\nCevap B (Özkütle 5 kat, Basınç 2 atm)."
