        "solution": "İdeal bir gazda, Sıcaklık (T) ve Mol (n) sabitse; \"Basınç ile Hacmin Çarpımı ($P \\cdot V$)\" DAİMA SABİTTİR. (Hacim yarıya düşerse basınç 2 katına çıkar ama çarpımları hep aynı sayıyı verir: $2 \\times 5 = 10$, $4 \\times 2.5 = 10$, $10 \\times 1 = 10$ gibi).\nBu nedenle, grafik yatay eksende (P) ne kadar ilerlerse ilerlesin (Basınç artsa da), y eksenindeki değer ($P \\cdot V$ değeri) HİÇ DEĞİŞMEYECEK (Sabit kalacak), \"Yatay (sabit) bir doğru\" olacaktır. (C)."
