        "difficulty": "medium",
        "solution": "Kap çelik (Sabit Hacim). Gaz kaçağı yok (Kütle Sabit). Sıcaklık ($T$) yarıya düştü.\nI. Gay Lussac (P-T orantısı). Hacim sabit, Kelvin yarıya düşerse P(Basınç) tam YARIYA DÜŞER. (I doğru).\nII. Hacim ($V$) SABİT (çelik kap). Kütle ($m$) SABİT. O halde Yoğunluk ($d = m/V$) KESİNLİKLE DEĞİŞMEZ. (Yarıya düşer demek YANLIŞTIR).\nIII. Kinetik Enerji yarıya düşer (T ile orantılıdır). Ancak \"Hız\", T'nin KAREKÖKÜ ($\\sqrt{T}$) ile orantılıdır. T yarıya düşerse, hız $\\sqrt{1/2}$ katına düşer. (Yani tam yarıya / 0.5'e değil, yaklaşık 0.7 katına düşer). (Hız yarıya düşer lafı KESİNLİKLE YANLIŞTIR).\nCevap II ve III'tür (C)."
